import React, { useState, useEffect } from "react";
import "./ViewTasks.css";
import Navbar from "../components/navbar";
import Footer from "../components/footer";
import StudentSidebar from "../components/StudentSidebar";
import axios from "axios";

const ViewTasks = () => {
  const formatDate = (dateString) => {
    const date = new Date(dateString);
    return date.toLocaleDateString("en-US", {
      year: "numeric",
      month: "short",
      day: "numeric",
    });
  };

  const user = JSON.parse(localStorage.getItem("users"));
  const [milestones, setMilestones] = useState([]);
  const [tasks, setTasks] = useState([]);
  const [group, setGroup] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [students, setStudents] = useState({});

  // New milestone input
  const [newMilestone, setNewMilestone] = useState({
    title: "",
    dueDate: "",
    status: "Pending",
  });

  // New task input
  const [newTask, setNewTask] = useState({
    title: "",
    status: "Pending",
    milestoneId: "",
  });

  // Fetch student's group and related data
  useEffect(() => {
    const fetchData = async () => {
      try {
        // Get current student
        const studentRes = await axios.get(
          `http://localhost:5000/api/student/user/${user.id}`
        );
        const student = studentRes.data;

        if (!student.isGrouped) {
          setError("You are not in a group yet. Please join a group to view tasks.");
          setLoading(false);
          return;
        }

        // Get student's group - Updated to send regNo in body
        const groupRes = await axios.post(
          "http://localhost:5000/api/group/student",
          { regNo: student.regNo }
        );
        const groupData = groupRes.data;
        setGroup(groupData);

        // Get all students in the group to map IDs to names
        const studentsRes = await Promise.all(
          groupData.studentsRegno.map((regNo) =>
            axios.post("http://localhost:5000/api/student", { regNo })
          )
        );
        const studentsData = studentsRes.reduce((acc, res) => {
          const student = res.data;
          acc[student.userId] = student.studentName;
          return acc;
        }, {});
        setStudents(studentsData);

        // Get milestones for the group's project
        const milestonesRes = await axios.get(
          `http://localhost:5000/api/milestone/project/${groupData.projectID}`
        );
        const milestonesData = milestonesRes.data;
        setMilestones(milestonesData);

        // Get all tasks for these milestones
        const taskPromises = milestonesData.map((milestone) =>
          axios.get(`http://localhost:5000/api/task/milestone/${milestone._id}`)
        );
        const tasksResults = await Promise.all(taskPromises);
        const allTasks = tasksResults.flatMap((res) => res.data);
        setTasks(allTasks);

        setLoading(false);
      } catch (err) {
        setError(err.response?.data?.message || "Failed to fetch data");
        setLoading(false);
      }
    };

    fetchData();
  }, [user.id]);

  // Add new milestone
  const handleAddMilestone = async () => {
    if (!newMilestone.title.trim() || !newMilestone.dueDate) {
      alert("Please fill in all milestone fields.");
      return;
    }

    try {
      const milestoneData = {
        ...newMilestone,
        projectID: group.projectID,
      };

      const res = await axios.post(
        "http://localhost:5000/api/milestone",
        milestoneData
      );
      setMilestones([...milestones, res.data]);
      setNewMilestone({ title: "", dueDate: "", status: "Pending" });
    } catch (err) {
      alert(err.response?.data?.message || "Failed to add milestone");
    }
  };

  // Add new task
  const handleAddTask = async (milestoneId) => {
    if (!newTask.title.trim()) {
      alert("Please enter a task title.");
      return;
    }

    try {
      const taskData = {
        ...newTask,
        milestoneId,
        uploadedBy: user.id,
      };

      const res = await axios.post("http://localhost:5000/api/task", taskData);
      setTasks([...tasks, res.data]);
      setNewTask({ title: "", status: "Pending", milestoneId: "" });
    } catch (err) {
      alert(err.response?.data?.message || "Failed to add task");
    }
  };

  // Update task status
  const handleUpdateTaskStatus = async (taskId, newStatus) => {
    try {
      const res = await axios.patch(`http://localhost:5000/api/task/${taskId}`, {
        status: newStatus,
      });

      setTasks(tasks.map((task) => (task._id === taskId ? res.data : task)));
    } catch (err) {
      alert(err.response?.data?.message || "Failed to update task");
    }
  };

  if (loading) {
    return (
      <div className="tasks-container">
        <Navbar />
        <div className="content-wrapper">
          <StudentSidebar />
          <div className="main-content">
            <div className="loading-spinner">Loading...</div>
          </div>
        </div>
        <Footer />
      </div>
    );
  }

  if (error) {
    return (
      <div className="tasks-container">
        <Navbar />
        <div className="content-wrapper">
          <StudentSidebar />
          <div className="main-content">
            <div className="error-message">{error}</div>
          </div>
        </div>
        <Footer />
      </div>
    );
  }

  if (!group) {
    return (
      <div className="tasks-container">
        <Navbar />
        <div className="content-wrapper">
          <StudentSidebar />
          <div className="main-content">
            <div>You are not in a group yet. Please join a group to view tasks.</div>
          </div>
        </div>
        <Footer />
      </div>
    );
  }

  return (
    <div className="tasks-container">
      <Navbar />
      <div className="content-wrapper">
        <StudentSidebar />
        <div className="main-content">
          <h1 className="tasks-title">Manage Milestones and Tasks</h1>
          <div className="group-info">
            <h3>Group: {group.groupNo}</h3>
            <p>Project ID: {group.projectID}</p>
          </div>

          {/* Input Field for Adding a Milestone */}
          <div className="milestone-section">
            <h3>Add New Milestone</h3>
            <div className="form-group">
              <label>Title:</label>
              <input
                type="text"
                value={newMilestone.title}
                onChange={(e) =>
                  setNewMilestone({ ...newMilestone, title: e.target.value })
                }
                placeholder="Milestone title"
              />
            </div>
            <div className="form-group">
              <label>Due Date:</label>
              <input
                type="date"
                value={newMilestone.dueDate}
                onChange={(e) =>
                  setNewMilestone({ ...newMilestone, dueDate: e.target.value })
                }
              />
            </div>
            <button className="add-button" onClick={handleAddMilestone}>
              Add Milestone
            </button>
          </div>

          {/* List of Milestones with Tasks */}
          <div className="milestone-list">
            <h2>Current Milestones</h2>
            {milestones.length === 0 ? (
              <p>No milestones found. Add one above.</p>
            ) : (
              milestones.map((milestone) => (
                <div key={milestone._id} className="milestone-item">
                  <div className="milestone-header">
                    <h3>{milestone.title}</h3>
                    <div className="milestone-meta">
                      <span
                        className={`status-badge ${milestone.status.toLowerCase()}`}
                      >
                        {milestone.status}
                      </span>
                      <span>Due: {formatDate(milestone.dueDate)}</span>
                    </div>
                  </div>

                  {/* Input Fields for Adding a Task to the Milestone */}
                  <div className="task-section">
                    <h4>Add New Task</h4>
                    <div className="form-group">
                      <label>Task Title:</label>
                      <input
                        type="text"
                        value={newTask.title}
                        onChange={(e) =>
                          setNewTask({
                            ...newTask,
                            title: e.target.value,
                            milestoneId: milestone._id,
                          })
                        }
                        placeholder="Task title"
                      />
                    </div>
                    <button
                      className="add-button"
                      onClick={() => handleAddTask(milestone._id)}
                      disabled={!newTask.title.trim()}
                    >
                      Add Task
                    </button>

                    {/* Table of Tasks Under the Milestone */}
                    <div className="tasks-table">
                      <h4>Tasks</h4>
                      {tasks.filter((task) => task.milestoneId === milestone._id)
                        .length === 0 ? (
                        <p>No tasks for this milestone yet.</p>
                      ) : (
                        <table>
                          <thead>
                            <tr>
                              <th>Task</th>
                              <th>Status</th>
                              <th>Created By</th>
                              <th>Created At</th>
                              <th>Actions</th>
                            </tr>
                          </thead>
                          <tbody>
                            {tasks
                              .filter((task) => task.milestoneId === milestone._id)
                              .map((task) => (
                                <tr key={task._id}>
                                  <td>{task.title}</td>
                                  <td>
                                    <span
                                      className={`status-badge ${task.status.toLowerCase()}`}
                                    >
                                      {task.status}
                                    </span>
                                  </td>
                                  <td>{students[task.uploadedBy] || "Unknown"}</td>
                                  <td>{formatDate(task.createdAt)}</td>
                                  <td>
                                    {task.status !== "Completed" && (
                                      <button
                                        className="action-button complete-button"
                                        onClick={() =>
                                          handleUpdateTaskStatus(task._id, "Completed")
                                        }
                                      >
                                        Mark as Completed
                                      </button>
                                    )}
                                  </td>
                                </tr>
                              ))}
                          </tbody>
                        </table>
                      )}
                    </div>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default ViewTasks;
